using ArchLucid.Contracts.Alerts;using ArchLucid.Core.Pagination;namespace ArchLucid.Persistence.Alerts;internal static class AlertRecordRepositoryCore{public const int MaxListTake=500;public static void ValidateAlertKeysetCursor(DateTime? c,Guid? a){if(c.HasValue!=a.HasValue)throw new ArgumentException();}public static int ClampListTake(int t)=>Math.Clamp(t<=0?50:t,1,MaxListTake);public static int ClampPagedTake(int t)=>Math.Clamp(t,1,PaginationDefaults.MaxPageSize);public static int ClampKeysetTake(int t)=>Math.Clamp(t,1,PaginationDefaults.MaxPageSize);public static int ClampPagedSkip(int s)=>Math.Max(s,0);public static bool MatchesScope(AlertRecord a,Guid t,Guid w,Guid p){ArgumentNullException.ThrowIfNull(a);return a.TenantId==t&&a.WorkspaceId==w&&a.ProjectId==p;}public static IEnumerable<AlertRecord> FilterInbox(IEnumerable<AlertRecord> a,Guid t,Guid w,Guid p,string? s,bool inc){ArgumentNullException.ThrowIfNull(a);return a.Where(x=>MatchesScope(x,t,w,p)).Where(x=>inc||!x.IsArchived).Where(x=>string.IsNullOrWhiteSpace(s)||string.Equals(x.Status,s,StringComparison.OrdinalIgnoreCase));}public static IOrderedEnumerable<AlertRecord> OrderForInbox(IEnumerable<AlertRecord> a){ArgumentNullException.ThrowIfNull(a);return a.OrderByDescending(x=>x.CreatedUtc).ThenByDescending(x=>x.AlertId);}public static AlertsInboxSummaryDto ComputeInboxSummary(IEnumerable<AlertRecord> a){ArgumentNullException.ThrowIfNull(a);var s=a.Where(x=>!x.IsArchived).ToList();return new AlertsInboxSummaryDto{OpenCount=s.Count(x=>string.Equals(x.Status,AlertStatus.Open,StringComparison.OrdinalIgnoreCase)),AcknowledgedCount=s.Count(x=>string.Equals(x.Status,AlertStatus.Acknowledged,StringComparison.OrdinalIgnoreCase)),ResolvedCount=s.Count(x=>string.Equals(x.Status,AlertStatus.Resolved,StringComparison.OrdinalIgnoreCase)),BlockingCount=s.Count(x=>string.Equals(x.Status,AlertStatus.Open,StringComparison.OrdinalIgnoreCase)&&(string.Equals(x.Severity,AlertSeverity.Critical,StringComparison.OrdinalIgnoreCase)||string.Equals(x.Severity,AlertSeverity.High,StringComparison.OrdinalIgnoreCase))),LastEvaluatedUtc=s.Count==0?null:s.Select(x=>x.LastUpdatedUtc??x.CreatedUtc).Max()};}}